<?php require_once __DIR__.'/includes/auth.php'; require_role(['admin','hiring_manager']); if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check(); $action=$_POST['action']??''; if($action==='period'){ $s=db()->prepare('INSERT INTO pay_periods(name,starts_on,ends_on) VALUES(?,?,?)'); $s->execute([trim($_POST['name']),$_POST['starts_on'],$_POST['ends_on']]); audit('pay_period_create','pay_period',(int)db()->lastInsertId()); flash('success','Pay period created.'); } header('Location: payroll.php'); exit; } $periods=db()->query('SELECT p.*,COUNT(pe.id) entry_count,COALESCE(SUM(pe.net_pay),0) total_net FROM pay_periods p LEFT JOIN payroll_entries pe ON pe.pay_period_id=p.id GROUP BY p.id ORDER BY p.starts_on DESC')->fetchAll(); $pageTitle='Payroll Foundation'; include __DIR__.'/includes/header.php'; ?><div class="page-heading"><div><span class="eyebrow">HR + payroll foundation</span><h1>Payroll periods</h1><p>Prepare pay periods and track compensation data before payroll processing.</p></div></div><?php if($msg=take_flash()): ?><div class="toast success"><?=htmlspecialchars($msg)?></div><?php endif; ?><div class="card"><div class="section-heading"><div><span class="eyebrow">Create period</span><h2>New pay period</h2></div></div><form class="form-grid" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="period"><label>Name<input required name="name" placeholder="March 1–15, 2026"></label><label>Starts on<input required type="date" name="starts_on"></label><label>Ends on<input required type="date" name="ends_on"></label><div><button class="button primary">Create period</button></div></form></div><div class="card"><div class="section-heading"><div><span class="eyebrow">Payroll register</span><h2>Periods</h2></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Dates</th><th>Status</th><th>Entries</th><th>Net total</th></tr></thead><tbody><?php foreach($periods as $period): ?><tr><td><strong><?=htmlspecialchars($period['name'])?></strong></td><td><?=htmlspecialchars($period['starts_on'])?> — <?=htmlspecialchars($period['ends_on'])?></td><td><span class="badge"><?=htmlspecialchars($period['status'])?></span></td><td><?=$period['entry_count']?></td><td><?=number_format((float)$period['total_net'],2)?> PHP</td></tr><?php endforeach; ?></tbody></table></div></div><?php include __DIR__.'/includes/footer.php'; ?>
